if (!defined('ABSPATH') || strpos(DB_NAME,'idlm_test_')!==0) { exit(1); }
function idlm_review_http_fixture(): array {
    global $wpdb;$a=idlm_atomic_http_lead();$b=idlm_atomic_http_lead();$wpdb->update($wpdb->prefix.'idlm_leads',array('phone'=>'91'.random_int(7000000000,7999999999)),array('id'=>$b));$data=array('first_name'=>'PII-SYNTHETIC-HELD','email'=>$wpdb->get_var("SELECT email FROM {$wpdb->prefix}idlm_leads WHERE id={$a}"),'phone'=>$wpdb->get_var("SELECT phone FROM {$wpdb->prefix}idlm_leads WHERE id={$b}"),'source'=>'Website','fb_lead_id'=>wp_generate_uuid4());
    $r=IDLM_DB::upsert_inbound_lead($data,'website');idlm_http_check(is_array($r)&&!empty($r['review_id']),'Review capture failed: '.IDLM_DB::get_last_validation_error());return array((int)$r['review_id'],$a,$b,$data);
