function idlm_review_http_nonce(int $id,string $actor='admin'): string {
    $r=idlm_http_request('/identity-reviews',array('after'=>$id-1),$actor,false);idlm_http_check($r['status']===200,'Manager page failed: '.$r['body']);$doc=new DOMDocument();@$doc->loadHTML($r['body']);$xpath=new DOMXPath($doc);$nonce=$xpath->evaluate("string(//form[input[@name='review_id' and @value='{$id}']]//input[@name='_wpnonce']/@value)");idlm_http_check($nonce!=='','Review-specific nonce missing');return $nonce;
}
function idlm_review_http_post(int $id,string $decision,int $lead,string $nonce,string $actor='admin'): array {
    return idlm_http_request('/wp-admin/admin-post.php',array('action'=>'idlm_resolve_identity_review','review_id'=>$id,'decision'=>$decision,'lead_id'=>$lead,'note'=>'Synthetic verified HTTP decision','_wpnonce'=>$nonce),$actor);
}
idlm_http_case('T02-H-CORE008-manager-page-is-escaped-paged-and-form-has-bound-nonce-and-labels',static function():void {
    global $wpdb,$users;[$id]=idlm_review_http_fixture();$u=get_userdata($users['manager']);$u->add_cap('idlm_access_leads');$u->add_cap('idlm_assign_leads');delete_user_meta($users['manager'],'idlm_crm_access_disabled');$wpdb->update($wpdb->prefix.'idlm_inbound_submission_reviews',array('source'=>'<script>PII-SYNTHETIC</script>'),array('id'=>$id));$r=idlm_http_request('/identity-reviews',array('after'=>$id-1),'manager',false);idlm_http_check($r['status']===200,'Manager denied');idlm_http_check(strpos($r['body'],'&lt;script&gt;')!==false&&strpos($r['body'],'<script>PII-SYNTHETIC</script>')===false,'Unsafe review output');$nonce=idlm_review_http_nonce($id,'manager');idlm_http_check(strlen($nonce)>0,'Nonce absent');idlm_http_check(strpos($r['body'],'for="note-'.$id.'"')!==false,'Reason lacks label');
});
