    foreach(array('',$foreign,$manager)as$nonce){$before=idlm_http_snapshot();$r=idlm_review_http_post($id,'separate',0,$nonce);idlm_http_check($r['status']===403,'Bad nonce allowed');idlm_http_check($before===idlm_http_snapshot(),'Bad nonce changed state');}
