foreach(array('matched','separate','rejected')as$decision){idlm_http_case('T02-H-CORE008-authorized-'.$decision.'-persists-once-and-stale-form-cannot-repeat',static function()use($decision):void {
    global $wpdb;[$id,$a,$b,$data]=idlm_review_http_fixture();$nonce=idlm_review_http_nonce($id);$r=idlm_review_http_post($id,$decision,$a,$nonce);idlm_http_check($r['status']===302,'Decision failed: '.$r['body']);$row=$wpdb->get_row("SELECT * FROM {$wpdb->prefix}idlm_inbound_submission_reviews WHERE id={$id}");idlm_http_check($row->status===$decision&&!empty($row->resolved_at),'Audit decision absent');$before=idlm_http_snapshot();$r=idlm_review_http_post($id,'separate',0,$nonce);idlm_http_check($r['status']===409,'Stale decision accepted');idlm_http_check($before===idlm_http_snapshot(),'Stale form changed aggregate');
    if($decision==='rejected'){$replay=idlm_atomic_webhook($data);$json=json_decode($replay['body'],true);idlm_http_check($replay['status']===202&&$json['requires_identity_review']===false&&$json['review_status']==='rejected','Rejected external replay was represented as pending');idlm_http_check($before===idlm_http_snapshot(),'Rejected webhook replay changed state');}
});}
